c='''def top_five(products):
    ordered = products[:]
    for i in range(len(ordered)-1):
        best = i
        for j in range(i+1, len(ordered)):
            if ordered[j].price > ordered[best].price:
                best = j
        ordered[i], ordered[best] = ordered[best], ordered[i]
    return ordered[:5]'''
add('12:b',['B2.4.3','B2.2.2'],'Construct top_five(products),returning the five most expensive Product objects in descending price order. There are at least five objects,each with price. Implement selection sort yourself rather than using a sorting built-in; leave the original list order unchanged. Equal-price order may be arbitrary.','One solution:\n'+c,[(1,'Copies list and returns first five objects.'),(1,'Correct outer pass and best-index initialization.'),(1,'Scans remaining suffix with correct bounds.'),(1,'Selects greatest price.'),(1,'Swaps selected object into position,producing descending order.')],[26],status='B',code=c,test_code=c+'''\nfrom types import SimpleNamespace as O
xs=[O(price=v) for v in [2,9,4,9,1,7]]
r=top_five(xs)
assert [p.price for p in r]==[9,9,7,4,2] and [p.price for p in xs]==[2,9,4,9,1,7]
assert len(top_five([O(price=1) for _ in range(5)]))==5''',check='Executed ties,exact five and original-list preservation.')
c='''def commission(products):
    total = 0
    for product in products:
        if product.sold:
            total += product.price
    return total * 0.12'''
